#include <iostream>
#include <vector>
#include <cassert>

using namespace std;

#define FOR(i, a, b) for (int i = (a); i < (b); ++i)
#define REP(i, n) FOR(i, 0, n)

typedef long long LL;

const int MOD = 1000000007;

int sum_mod(int a, int b) {
    int s = a + b;
    if (s >= MOD) s -= MOD;
    return s;
}

int product_mod(int a, int b) {
    return (LL)a * b % MOD;
}

const int DIM = 32;

struct Matrix {
    int m[DIM][DIM];
    Matrix() { for (int i = 0; i < DIM; ++i) for (int j = 0; j < DIM; ++j) m[i][j] = 0; }
    int* operator[](int i) { return m[i]; }
    friend Matrix operator*(const Matrix& A, const Matrix& B) {
        Matrix R;
        for (int i = 0; i < DIM; ++i)
            for (int j = 0; j < DIM; ++j)
                for (int k = 0; k < DIM; ++k)
                    R[i][j] = sum_mod(R[i][j], product_mod(A[i][k], B[k][j]));
        return R;
    }
};

const int MAX_D = 64;
const int MAX_K = 32;

Matrix f[MAX_D];
int k;

Matrix generate_matrix(int n, int offset) {
    Matrix M;
    for (int i = 0; i <= k; ++i)
        for (int j = 0; j <= k; ++j) {
            int ni = (i == k) ? i : (i + offset) % k;
            int nj = (j == k) ? j : (j + offset) % k;
            M[ni][nj] = f[n][i][j];
        }
    return M;
}

int compute_sum_of_digits(ll n) {
    int sum = 0;
    while (n > 0) {
        sum += n % k;
        n /= k;
    }
    return sum % k;
}

int main() {
    LL n;
    int base;
    cin >> n >> base;
    k = base;

    int digit_count = 0;
    LL temp = n;
    while (temp > 0) {
        temp /= k;
        ++digit_count;
    }

    Matrix identity;
    for (int i = 0; i <= k; ++i) identity[i][i] = 1;

    f[0] = identity;
    for (int i = 0; i <= k; ++i) f[0][i][0] = 1;

    for (int i = 1; i < digit_count; ++i) {
        f[i] = identity;
        for (int j = 0; j < k; ++j)
            f[i] = f[i] * generate_matrix(i - 1, j);
    }

    LL current = 0;
    LL power = 1;

    --digit_count;
    for (int i = 0; i < digit_count; ++i) power *= k;

    Matrix result = identity;
    while (current < n) {
        assert(digit_count >= 0);
        while (current + power <= n) {
            result = result * generate_matrix(digit_count, compute_sum_of_digits(current));
            current += power;
        }
        power /= k;
        --digit_count;
    }

    int total_sum = 0;
    for (int i = 0; i <= k; ++i)
        total_sum = sum_mod(total_sum, result[k][i]);
    cout << total_sum << "\n";
    return 0;
}
